content.query:
// Documentation page views, most and least read.
// referrerKind describes how the FIRST docs page of a visit was reached; later
// in-session navigations are reported as "internal" by design.
// Bottom rows are candidates for merging or deletion; top rows are where
// visual and structural investment pays back most.
customEvents
| where name == "Docs_PageView"
| where timestamp > ago(30d)
| extend slug = tostring(customDimensions.slug),
         referrerKind = tostring(customDimensions.referrerKind)
// "internal" covers any same-site referrer, which includes doc-to-doc reading —
// it is not "arrived from the app", so the column is named for what it measures.
| summarize views = count(),
            readers = dcount(user_Id),
            fromSearch = countif(referrerKind == "search"),
            fromInternal = countif(referrerKind == "internal")
        by slug
| extend searchShare = round(100.0 * fromSearch / views, 1)
| order by views desc

// Which app screens send people to the documentation — the closest direct
// measure of where the product itself is confusing.
// Returns no rows until in-app help ships (phase 4).
customEvents
| where name == "Docs_HelpLinkClick"
| where timestamp > ago(30d)
| extend source = tostring(customDimensions.source),
         slug = tostring(customDimensions.slug)
| summarize clicks = count(), people = dcount(user_Id) by source, slug
| order by clicks desc

// Whether search is working when it does return results: how often a result is
// actually clicked, and how far down. Returns no rows until phase 2b.
let searches =
    customEvents
    | where name == "Docs_Search" and timestamp > ago(30d)
    | extend query = tolower(trim(" ", tostring(customDimensions.query)))
    | where isnotempty(query)
    | summarize searches = count() by query;
let clicks =
    customEvents
    | where name == "Docs_SearchResultClick" and timestamp > ago(30d)
    | extend query = tolower(trim(" ", tostring(customDimensions.query))),
             rank = toint(customDimensions.rank)
    | summarize clicks = count(), avgRank = round(avg(rank), 1) by query;
searches
| join kind=leftouter clicks on query
// Clicks per search, NOT a click-through percentage: Docs_SearchResultClick
// carries no search-attempt id, and one search can produce several clicks, so
// this ratio can legitimately exceed 1. Treat >1 as "explored several results".
| extend clicksPerSearch = round(1.0 * coalesce(clicks, 0) / searches, 2)
| project query, searches, clicks = coalesce(clicks, 0), clicksPerSearch, avgRank
| order by searches desc
